import functools

def minTravelTime(l, n, k, position, time):
    # After exactly k merges, n-k signs remain (including signs 0 and n-1, which are
    # never removed). Merging pushes time rightward, so a remaining sign c accumulates
    # time[p+1..c] where p is the previous remaining sign. The segment c->next uses
    # that accumulated per-km time. DP over (current sign, previous sign, signs kept).
    T = [0] * (n + 1)
    for i in range(n):
        T[i + 1] = T[i] + time[i]

    def Tp(x):
        return 0 if x < 0 else T[x + 1]

    m = n - k

    @functools.lru_cache(maxsize=None)
    def dp(c, p, cnt):
        if cnt == m:
            return 0 if c == n - 1 else float('inf')
        if c == n - 1:
            return float('inf')
        acc = Tp(c) - Tp(p)
        best = float('inf')
        for x in range(c + 1, n):
            val = (position[x] - position[c]) * acc + dp(x, c, cnt + 1)
            if val < best:
                best = val
        return best

    return dp(0, -1, 1)
